const STEP_FRAMES = 20;

/**
 * The first step, which starts from a standstill and so is not a `STEP`: the
 * first row holds the slot until frame 11.5, then the strip pulls away slowly
 * and catches the rhythm by the time the second row rests at 34.72.
 */
