const FIRST_REST = 34.72;

/**
 * Where in a step the slot changes hands, as a share of the pitch.
 *
 * Not half. The incoming row takes the focus when it is still 0.64 of a pitch
 * out — between 0.319 and 0.388 on every swap in the recording — which is why
 * each new row arrives already sharp instead of popping in at the midpoint.
 */
const SWAP = 0.36;

/**
 * The strip freezes this many frames before the last row would rest, still
 * creeping at 1.15px a frame. Measured, and it is the beat that makes the stop
 * read as a click landing rather than as the wheel running out.
 */
const STOP_EARLY = 1.12;

/**
 * How visible a row is by its distance from the slot, in px, as (distance,
 * opacity). Read off the peak ink of every row in every frame of the Google
 * cycle and normalised to the row in the slot. It is a property of position,
 * not of focus: the row in the slot is faded by it too while it is arriving.
 */
