/** What a prop falls back to when Studio does not pass it, reset included. */
const BrandWheelDefaults = {
  lead: "launch on",
  items: "X, YouTube, LinkedIn, Instagram, TikTok, Product Hunt",
  cursor: true,
  mode: "light",
  speed: 1,
} satisfies Partial<BrandWheelElementProps>;

/** The Inspector's controls. Timing, transform, crop and premount come with `wrapInSequence`. */
const BrandWheelSchema = {
  lead: {
    type: "text-content",
    default: "launch on",
    description: "Lead word",
  },
  items: {
    type: "text-content",
    default: "X, YouTube, LinkedIn, Instagram, TikTok, Product Hunt",
    description: "Brands (comma separated)",
  },
  cursor: {
    type: "boolean",
    default: true,
    description: "Click the last one",
    keyframable: false,
  },
  mode: {
    type: "enum",
    default: "light",
    description: "Theme",
    variants: { light: {}, dark: {} },
  },
  fontFamily: { type: "font-family", default: undefined, description: "Font" },
  speed: {
    type: "number",
    default: 1,
    min: 0.25,
    max: 4,
    step: 0.25,
    description: "Speed",
    hiddenFromList: false,
    keyframable: false,
  },
} as const satisfies InteractivitySchema;

/**
 * In over the first frames, out over the last. Opacity only: nothing moves, so
 * no glyph can snap to the pixel grid on the way out.
 */
function BrandWheelFade({ children }: { children: ReactNode }) {
  const frame = useCurrentFrame();
  const enter = Math.min(1, (frame + 1) / 6);
  const { durationInFrames } = useVideoConfig();
  const left = Math.min(1, Math.max(0, (durationInFrames - 1 - frame) / 12));
  const leave = left * left;
  return (
    <AbsoluteFill showInTimeline={false} style={{ opacity: enter * leave }}>
      {children}
    </AbsoluteFill>
  );
}

const BrandWheelInner = forwardRef<HTMLDivElement, BrandWheelElementProps>(
  ({ style, ...props }, ref) => {
    // The layer's length, from the Sequence `wrapInSequence` puts around this.
    const { durationInFrames } = useVideoConfig();
    const rest = { ...BrandWheelDefaults, ...props };
    // The scene measures its copy once, on mount. An Inspector edit changes the
    // props without remounting it, so the key does.
    const key = JSON.stringify(props, (k, v) =>
      k === "children" ? undefined : v,
    );

    // width/height are what useVideoConfig() reports inside this Sequence, so
    // the scene lays itself out in its stage rather than the whole composition.
    // It is not a layer of its own: the one Studio shows is the wrapper's.
    return (
      <Sequence
        layout="none"
        showInTimeline={false}
        durationInFrames={durationInFrames}
        width={1280}
        height={720}
      >
        <div
          ref={ref}
          style={{
            position: "relative",
            width: 1280,
            height: 720,
            overflow: "hidden",
            color: "black",
            fontFamily: "initial",
            fontSize: 16,
            fontStyle: "normal",
            fontVariant: "normal",
            fontWeight: 400,
            fontStretch: "normal",
            fontKerning: "auto",
            fontFeatureSettings: "normal",
            fontVariationSettings: "normal",
            lineHeight: "normal",
            letterSpacing: "normal",
            wordSpacing: "normal",
            textAlign: "start",
            textIndent: 0,
            textTransform: "none",
            textShadow: "none",
            textRendering: "auto",
            whiteSpace: "normal",
            wordBreak: "normal",
            overflowWrap: "normal",
            hyphens: "manual",
            direction: "ltr",
            visibility: "visible",
            ...style,
          }}
        >
          <BrandWheelFade>
            <BrandWheelScene key={key} {...rest} />
          </BrandWheelFade>
        </div>
      </Sequence>
    );
  },
);

export const BrandWheel = Interactive.withSchema({
  Component: BrandWheelInner,
  componentName: "<BrandWheel>",
  schema: BrandWheelSchema,
  wrapInSequence: true,
});
